import { assertEquals, assertRejects } from 'https://deno.land/std@0.224.0/assert/mod.ts';
import { PDFDocument } from 'npm:pdf-lib@1.17.1';

import { fillMembershipPdfForm, type MembershipApplication } from './pdf.ts';

// The template is generated by scripts/membership-form/build.ts. Filling it here is what
// catches a field that was renamed or dropped there: pdf-lib throws on an unknown name, and
// otherwise that would only show up as a failed submission in production.
const TEMPLATE = new URL('../../../src/assets/forms/Mitgliedsantrag_26-10.pdf', import.meta.url);

const application: MembershipApplication = {
  membership_type: 'youth',
  name: 'Müller-Lüdenscheidt',
  firstname: 'Jörg',
  birthday: '2014-03-09',
  birthplace: 'Fürth',
  nationality: 'deutsch',
  street: 'Große Straße 12',
  plz_town: '90402 Nürnberg',
  tel: '',
  fax: '',
  mobile: '0170 1234567',
  email: 'familie.mueller@example.com',
  joindate_month: '01',
  joindate_year: '2027',
  sepa_account_holder_name: 'Müller',
  sepa_account_holder_firstname: 'Anna',
  sepa_iban: 'de89 3704 0044 0532 0130 00',
  sepa_bic: 'COBADEFFXXX',
  sepa_bank: 'Commerzbank',
  recaptchaToken: '',
};

/** Fills the template without flattening, so the values can be read back by field name. */
async function fillAndRead(overrides: Partial<MembershipApplication> = {}) {
  const template = await Deno.readFile(TEMPLATE);
  const filled = await fillMembershipPdfForm(template, { ...application, ...overrides }, {
    flatten: false,
  });
  const form = (await PDFDocument.load(filled)).getForm();
  return (name: string) => form.getFieldMaybe(name) && form.getTextField(name).getText();
}

Deno.test('every membership type ticks its own box and no other', async () => {
  for (const type of ['adult', 'youth', 'support'] as const) {
    const read = await fillAndRead({ membership_type: type });
    assertEquals(read('membership_adult') ?? '', type === 'adult' ? 'X' : '');
    assertEquals(read('membership_youth') ?? '', type === 'youth' ? 'X' : '');
    assertEquals(read('membership_support') ?? '', type === 'support' ? 'X' : '');
  }
});

Deno.test('dates are written the way the paper form expects', async () => {
  const read = await fillAndRead();
  assertEquals(read('birthday'), '09.03.2014');
  assertEquals(read('joindate_month'), 'Januar');
  assertEquals(read('joindate_year'), '27');
});

Deno.test('a German IBAN goes one character per box, without spaces', async () => {
  const read = await fillAndRead();
  const iban = Array.from({ length: 22 }, (_, i) => read(`sepa_iban_${i + 1}`)).join('');
  assertEquals(iban, 'DE89370400440532013000');
  assertEquals(read('sepa_iban'), undefined);
  assertEquals(read('sepa_bic_1'), 'C');
  assertEquals(read('sepa_bic_11'), 'X');
});

Deno.test('an IBAN longer than the boxes is printed across the row instead', async () => {
  const read = await fillAndRead({ sepa_iban: 'MT84MALT011000012345MTLCAST001S' });
  assertEquals(read('sepa_iban'), 'MT84 MALT 0110 0001 2345 MTLC AST0 01S');
  assertEquals(read('sepa_iban_1') ?? '', '');
});

Deno.test('an unknown membership type is refused rather than leaving every box empty', async () => {
  const template = await Deno.readFile(TEMPLATE);
  await assertRejects(() =>
    fillMembershipPdfForm(template, {
      ...application,
      membership_type: 'other' as MembershipApplication['membership_type'],
    })
  );
});
